#!/usr/bin/env python3
"""Native SFN workflow-CMK log-delivery probe. Run from repository root.

python /tmp/stackd_encryption_logging_probe.py captures setup, executes fresh
STANDARD and EXPRESS controls, samples for 12 minutes, and cleans up in finally.
Only default credential-chain credentials are used; none are serialized.
"""
import copy
from datetime import datetime, timezone, timedelta
import json
import os
from pathlib import Path
import sys
import time
import uuid
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError

ROOT = Path.cwd()
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import observe
ACCOUNT = '000000000000'
REGION = 'us-west-2'
CALLER = f'arn:aws:iam::{ACCOUNT}:user/Delegated'
PREFIX = 'sd-enc-log-' + uuid.uuid4().hex[:10]
OUT = ROOT / 'testdata/aws/stepfunctions/encryption_logging.json'
SOURCE = Path(__file__).read_text()
CONFIG = Config(retries={'max_attempts': 2, 'mode': 'standard'}, connect_timeout=10, read_timeout=30)
SESSION = boto3.Session(region_name=REGION)
CLIENTS = {s: SESSION.client(s, config=CONFIG) for s in ('sts', 'iam', 'kms', 'logs', 'stepfunctions', 'cloudtrail')}
START = datetime.now(timezone.utc)
DATA = {
    'account': ACCOUNT, 'region': REGION, 'caller_arn': CALLER, 'prefix': PREFIX,
    'started_at': START.isoformat(),
    'scope': 'Six fresh workflow/key/execution-role/log-group tuples: Standard and Express for positive, missing delivery-principal Decrypt, and missing execution-role Logs SourceArn GenerateDataKey. Express uses synchronous and asynchronous starts. No log-group-at-rest CMK; no pre-existing resource mutations.',
    'serialization': 'Unmodified boto3 SDK response/error dictionaries including ResponseMetadata, with datetimes serialized to ISO-8601. CloudTrail LookupEvents retains only owned-prefix/key-correlated Events and records excluded counts. STS session credentials are never stored. Complete request policies and probe source retained. Log messages and request inputs contain synthetic nonsecret markers only.',
    'sources': [
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/encryption-at-rest.html', 'read_at': START.isoformat(), 'claims': ['Execution role log encryption uses kms:EncryptionContext:SourceArn = arn:aws:logs:<region>:<account>:*.', 'delivery.logs.amazonaws.com needs kms:Decrypt on workflow CMK.', 'Log-group-at-rest encryption is separate and optional.']},
        {'url': 'https://docs.aws.amazon.com/AmazonCloudWatchLogs/latest/APIReference/API_PutResourcePolicy.html', 'read_at': START.isoformat(), 'claims': ['resourceArn scopes a resource policy to one log group.']},
        {'path': 'scripts/aws/aws_cli.py', 'role': 'Read before capture; used for independent identity and cleanup verification.'},
        {'path': '/tmp/stackd_encryption_logging_probe.py', 'content': SOURCE}
    ],
    'observations': [], 'cases': [], 'cloudtrail_events': {}, 'sampling': [], 'cleanup': {},
    'bounds': ['CloudWatch Logs delivery is best effort; no finite empty sample proves permanent absence.', 'CloudTrail event history is eventually consistent; missing events do not prove KMS was not called.', 'Keys are unique per workflow and never shared across permission cases. Policies are not changed to create negative cases after warming. CMKs remain billable until scheduled deletion; PendingDeletion is not deleted.']
}

def now():
    return datetime.now(timezone.utc).isoformat()

def dump():
    OUT.write_text(json.dumps(DATA, indent=2, default=lambda x: x.isoformat() if isinstance(x, datetime) else str(x)) + '\n')

def call(label, service, operation, request=None, client=None, strict=True, transform=None):
    record = {'label': label, 'service': service, 'operation': operation, 'actor': 'default', 'request': copy.deepcopy(request or {}), 'started_at': now()}
    try:
        result = getattr(client or CLIENTS[service], operation)(**(request or {}))
        record['result'] = {'code': 'Success', 'output': transform(result) if transform else copy.deepcopy(result)}
    except ClientError as error:
        result = None
        record['result'] = {'code': error.response['Error']['Code'], 'error': error.response}
        if strict:
            DATA['observations'].append(record)
            record['finished_at'] = now()
            dump()
            raise
    record['finished_at'] = now()
    DATA['observations'].append(record)
    dump()
    return result

def setup():
    identity = observe('sts', 'get-caller-identity')
    DATA['cli_identity'] = identity
    assert identity['output']['Account'] == ACCOUNT and identity['output']['Arn'] == CALLER
    if 'account_resource_policies_before' not in DATA:
        DATA['account_resource_policies_before'] = call('account-policy-before', 'logs', 'describe_resource_policies', {'policyScope': 'ACCOUNT'})
    assert not DATA['account_resource_policies_before'].get('nextToken'), 'Unexpected account-policy pagination'
    for typ in ('STANDARD', 'EXPRESS'):
        for scenario in ('positive', 'no-delivery-decrypt', 'no-logs-generate'):
            name = PREFIX + '-' + typ.lower() + '-' + scenario
            if any(c['name'] == name and c.get('resource_policy_created') for c in DATA['cases']):
                continue
            case = {'id': typ.lower() + '-' + scenario, 'type': typ, 'scenario': scenario, 'name': name, 'role_name': name, 'role_arn': f'arn:aws:iam::{ACCOUNT}:role/{name}', 'machine_arn': f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{name}', 'group_name': '/aws/vendedlogs/states/' + name, 'executions': []}
            case['group_arn'] = f'arn:aws:logs:{REGION}:{ACCOUNT}:log-group:' + case['group_name']
            DATA['cases'].append(case)
            key_policy = {'Version': '2012-10-17', 'Statement': [{'Sid': 'OwnedAccountIAM', 'Effect': 'Allow', 'Principal': {'AWS': f'arn:aws:iam::{ACCOUNT}:root'}, 'Action': 'kms:*', 'Resource': '*'}]}
            if scenario != 'no-delivery-decrypt':
                key_policy['Statement'].append({'Sid': 'AllowWorkflowLogDelivery', 'Effect': 'Allow', 'Principal': {'Service': 'delivery.logs.amazonaws.com'}, 'Action': 'kms:Decrypt', 'Resource': '*'})
            case['key_policy'] = key_policy
            key = call(name + '-key', 'kms', 'create_key', {'Description': name, 'Policy': json.dumps(key_policy), 'KeyUsage': 'ENCRYPT_DECRYPT', 'KeySpec': 'SYMMETRIC_DEFAULT', 'Tags': [{'TagKey': 'native-probe', 'TagValue': PREFIX}]})
            case['key_arn'] = key['KeyMetadata']['Arn']
            case['key_id'] = key['KeyMetadata']['KeyId']
            trust = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'states.amazonaws.com'}, 'Action': 'sts:AssumeRole'}]}
            call(name + '-role', 'iam', 'create_role', {'RoleName': name, 'AssumeRolePolicyDocument': json.dumps(trust), 'Tags': [{'Key': 'native-probe', 'Value': PREFIX}]})
            case['role_created'] = True
            policy = {'Version': '2012-10-17', 'Statement': [
                {'Sid': 'LogDeliveryConfiguration', 'Effect': 'Allow', 'Action': ['logs:CreateLogDelivery', 'logs:GetLogDelivery', 'logs:UpdateLogDelivery', 'logs:DeleteLogDelivery', 'logs:ListLogDeliveries', 'logs:DescribeResourcePolicies', 'logs:DescribeLogGroups'], 'Resource': '*'},
                {'Sid': 'OwnedLogEvents', 'Effect': 'Allow', 'Action': ['logs:CreateLogStream', 'logs:PutLogEvents'], 'Resource': case['group_arn'] + ':*'},
                {'Sid': 'NormalWorkflowEncryption', 'Effect': 'Allow', 'Action': ['kms:GenerateDataKey', 'kms:Decrypt'], 'Resource': case['key_arn'], 'Condition': {'StringEquals': {'kms:EncryptionContext:aws:states:stateMachineArn': case['machine_arn']}}}
            ]}
            if scenario != 'no-logs-generate':
                policy['Statement'].append({'Sid': 'WorkflowLogGeneration', 'Effect': 'Allow', 'Action': 'kms:GenerateDataKey', 'Resource': case['key_arn'], 'Condition': {'StringEquals': {'kms:EncryptionContext:SourceArn': f'arn:aws:logs:{REGION}:{ACCOUNT}:*'}}})
            case['role_policy'] = policy
            call(name + '-role-policy', 'iam', 'put_role_policy', {'RoleName': name, 'PolicyName': PREFIX, 'PolicyDocument': json.dumps(policy)})
            case['inline_policy_created'] = True
            call(name + '-group', 'logs', 'create_log_group', {'logGroupName': case['group_name'], 'tags': {'native-probe': PREFIX}})
            case['group_created'] = True
            resource_policy = {'Version': '2012-10-17', 'Statement': [{'Sid': 'OwnedLogDelivery', 'Effect': 'Allow', 'Principal': {'Service': 'delivery.logs.amazonaws.com'}, 'Action': ['logs:CreateLogStream', 'logs:PutLogEvents'], 'Resource': case['group_arn'] + ':*', 'Condition': {'StringEquals': {'aws:SourceAccount': ACCOUNT}, 'ArnLike': {'aws:SourceArn': f'arn:aws:logs:{REGION}:{ACCOUNT}:*'}}}]}
            call(name + '-log-policy', 'logs', 'put_resource_policy', {'policyDocument': json.dumps(resource_policy), 'resourceArn': case['group_arn']})
            case['resource_policy_created'] = True
    DATA['role_propagation_wait'] = {'started_at': now(), 'seconds': 20}
    dump()
    time.sleep(20)
    DATA['role_propagation_wait']['finished_at'] = now()
    definition = json.dumps({'StartAt': 'Pass', 'States': {'Pass': {'Type': 'Pass', 'End': True}}})
    for case in DATA['cases']:
        request = {'name': case['name'], 'definition': definition, 'roleArn': case['role_arn'], 'type': case['type'], 'loggingConfiguration': {'level': 'ALL', 'includeExecutionData': True, 'destinations': [{'cloudWatchLogsLogGroup': {'logGroupArn': case['group_arn'] + ':*'}}]}, 'encryptionConfiguration': {'type': 'CUSTOMER_MANAGED_KMS_KEY', 'kmsKeyId': case['key_arn'], 'kmsDataKeyReusePeriodSeconds': 60}, 'tags': [{'key': 'native-probe', 'value': PREFIX}]}
        made = call(case['id'] + '-create-machine', 'stepfunctions', 'create_state_machine', request, strict=False)
        case['machine_created'] = bool(made)
        if not made:
            continue
        for mode in (('async',) if case['type'] == 'STANDARD' else ('sync', 'async')):
            op = 'start_sync_execution' if mode == 'sync' else 'start_execution'
            invocation = {'name': 'fresh-' + mode, 'stateMachineArn': case['machine_arn'], 'input': json.dumps({'probe': PREFIX, 'case': case['id'], 'mode': mode})}
            result = call(case['id'] + '-' + mode, 'stepfunctions', op, invocation, strict=False)
            case['executions'].append({'mode': mode, 'invoked_at': now(), 'response': result})
    DATA['setup_finished_at'] = now()
    dump()

def sample(label):
    window = {'label': label, 'started_at': now(), 'groups': {}}
    for case in DATA['cases']:
        if not case.get('group_created'):
            continue
        request = {'logGroupName': case['group_name'], 'startTime': int(START.timestamp() * 1000), 'endTime': int(time.time() * 1000), 'limit': 10000}
        events = []
        tokens = set()
        page = 0
        while True:
            response = call(case['id'] + '-logs-' + label + '-' + str(page), 'logs', 'filter_log_events', request, strict=False)
            if not response:
                break
            events.extend(response.get('events', []))
            token = response.get('nextToken')
            if not token or token in tokens:
                break
            tokens.add(token)
            request['nextToken'] = token
            page += 1
        workflow_events = []
        for event in events:
            try:
                message = json.loads(event['message'])
            except json.JSONDecodeError:
                continue
            if isinstance(message, dict) and message.get('execution_arn', '').startswith(f'arn:aws:states:{REGION}:{ACCOUNT}:'):
                workflow_events.append(message)
        window['groups'][case['id']] = {'event_count': len(events), 'workflow_event_count': len(workflow_events), 'workflow_event_types': [e.get('type') for e in workflow_events], 'pages': page + 1, 'pagination_complete': bool(response and not response.get('nextToken'))}
        if case['type'] == 'STANDARD':
            for execution in case['executions']:
                if execution['response']:
                    desc = call(case['id'] + '-execution-' + label, 'stepfunctions', 'describe_execution', {'executionArn': execution['response']['executionArn']}, strict=False)
                    execution['latest_description'] = desc
    window['finished_at'] = now()
    DATA['sampling'].append(window)
    dump()
    return window

def telemetry(label):
    keys = [c['key_id'] for c in DATA['cases'] if 'key_id' in c]
    next_token = None
    page = 0
    retained = 0
    end_time = datetime.now(timezone.utc)
    while True:
        request = {'LookupAttributes': [{'AttributeKey': 'EventSource', 'AttributeValue': 'kms.amazonaws.com'}], 'StartTime': START - timedelta(seconds=5), 'EndTime': end_time, 'MaxResults': 50}
        if next_token:
            request['NextToken'] = next_token
        def owned_only(result):
            nonlocal retained
            filtered = copy.deepcopy(result)
            filtered['Events'] = [e for e in result.get('Events', []) if PREFIX in e.get('CloudTrailEvent', '') or any(k in e.get('CloudTrailEvent', '') for k in keys)]
            filtered['excluded_unrelated_event_count'] = len(result.get('Events', [])) - len(filtered['Events'])
            for event in filtered['Events']:
                DATA['cloudtrail_events'][event['EventId']] = event
            retained += len(filtered['Events'])
            return filtered
        result = call('kms-cloudtrail-' + label + '-' + str(page), 'cloudtrail', 'lookup_events', request, strict=False, transform=owned_only)
        if not result or not result.get('NextToken'):
            break
        next_token = result['NextToken']
        page += 1
        time.sleep(0.6)
    DATA.setdefault('telemetry_samples', []).append({'label': label, 'finished_at': now(), 'retained_events': retained, 'pages': page + 1})
    dump()
    return retained

def cleanup():
    DATA['cleanup']['started_at'] = now()
    for case in DATA['cases']:
        if case.get('machine_created'):
            call(case['id'] + '-delete-machine', 'stepfunctions', 'delete_state_machine', {'stateMachineArn': case['machine_arn']}, strict=False)
    # Wait for asynchronous Standard state-machine deletion, not just request acceptance.
    deadline = time.monotonic() + 180
    pending = [c for c in DATA['cases'] if c.get('machine_created')]
    while pending and time.monotonic() < deadline:
        for case in list(pending):
            response = call(case['id'] + '-verify-machine-deletion', 'stepfunctions', 'describe_state_machine', {'stateMachineArn': case['machine_arn']}, strict=False)
            code = DATA['observations'][-1]['result']['code']
            if code == 'StateMachineDoesNotExist':
                case['machine_absent_verified'] = True
                pending.remove(case)
        if pending:
            time.sleep(5)
    for case in DATA['cases']:
        if case.get('resource_policy_created'):
            call(case['id'] + '-delete-resource-policy', 'logs', 'delete_resource_policy', {'resourceArn': case['group_arn']}, strict=False)
        if case.get('group_created'):
            call(case['id'] + '-delete-group', 'logs', 'delete_log_group', {'logGroupName': case['group_name']}, strict=False)
        if case.get('inline_policy_created'):
            call(case['id'] + '-delete-inline-policy', 'iam', 'delete_role_policy', {'RoleName': case['role_name'], 'PolicyName': PREFIX}, strict=False)
        if case.get('role_created'):
            call(case['id'] + '-delete-role', 'iam', 'delete_role', {'RoleName': case['role_name']}, strict=False)
        if case.get('key_id'):
            call(case['id'] + '-schedule-key-deletion', 'kms', 'schedule_key_deletion', {'KeyId': case['key_id'], 'PendingWindowInDays': 7}, strict=False)
    DATA['cleanup']['independent_cli_verification'] = []
    env = dict(os.environ, AWS_DEFAULT_REGION=REGION, AWS_REGION=REGION)
    for case in DATA['cases']:
        checks = [('stepfunctions', 'describe-state-machine', {'stateMachineArn': case['machine_arn']}), ('iam', 'get-role', {'RoleName': case['role_name']}), ('iam', 'list-role-policies', {'RoleName': case['role_name']}), ('logs', 'describe-log-groups', {'logGroupNamePrefix': case['group_name']}), ('logs', 'describe-resource-policies', {'policyScope': 'RESOURCE', 'resourceArn': case['group_arn']})]
        if case.get('key_id'):
            checks.append(('kms', 'describe-key', {'KeyId': case['key_id']}))
        for service, operation, request in checks:
            result = observe(service, operation, request, env)
            DATA['cleanup']['independent_cli_verification'].append({'case': case['id'], 'service': service, 'operation': operation, 'request': request, 'observed_at': now(), 'result': result})
            dump()
    DATA['account_resource_policies_after'] = call('account-policy-after', 'logs', 'describe_resource_policies', {'policyScope': 'ACCOUNT'})
    DATA['cleanup']['account_resource_policies_unchanged'] = DATA['account_resource_policies_before'].get('resourcePolicies') == DATA['account_resource_policies_after'].get('resourcePolicies')
    DATA['cleanup']['finished_at'] = now()
    dump()

def main():
    global DATA, PREFIX, START
    try:
        if '--resume' in sys.argv:
            DATA = json.loads(OUT.read_text())
            PREFIX = DATA['prefix']
            START = datetime.fromisoformat(DATA['started_at'])
            DATA['sources'][-1]['content'] = SOURCE
            DATA['capture_deviations'].append('Resumed saved capture in separate Python process; initial non-paginated sample is bounded, subsequent samples exhaust log pagination. No resource setup or execution was repeated.')
            dump()
        else:
            setup()
        sample('initial' if '--resume' not in sys.argv else 'resumed')
        telemetry('initial' if '--resume' not in sys.argv else 'resumed')
        baseline = datetime.fromisoformat(DATA['setup_finished_at']).timestamp()
        for seconds in (180, 420, 720):
            time.sleep(max(0, baseline + seconds - time.time()))
            sample(str(seconds) + 's')
            telemetry(str(seconds) + 's')
    except Exception as error:
        DATA['capture_error'] = {'type': type(error).__name__, 'message': str(error)}
        dump()
        raise
    finally:
        cleanup()
        DATA['finished_at'] = now()
        dump()

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Later Express starts without changing any resource configuration; separate output while primary capture runs."""
from datetime import datetime, timezone
import json
from pathlib import Path
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError
fixture = json.loads(Path('testdata/aws/stepfunctions/encryption_logging.json').read_text())
client = boto3.client('stepfunctions', region_name=fixture['region'], config=Config(connect_timeout=10, read_timeout=30, retries={'max_attempts': 2}))
output = {'source': Path(__file__).read_text(), 'reason': 'Original Express positive had no workflow logs at seven-minute sample. Later starts exercise settled delivery configuration without key/role policy changes; all negative cases remain isolated and have never successfully delivered workflow logs.', 'observations': []}
for case in fixture['cases']:
    if case['type'] != 'EXPRESS':
        continue
    for mode in ('sync', 'async'):
        operation = 'start_sync_execution' if mode == 'sync' else 'start_execution'
        request = {'stateMachineArn': case['machine_arn'], 'name': 'propagated-' + mode, 'input': json.dumps({'probe': fixture['prefix'], 'case': case['id'], 'mode': mode, 'after_delivery_settlement': True})}
        row = {'label': case['id'] + '-propagated-' + mode, 'case': case['id'], 'mode': mode, 'service': 'stepfunctions', 'operation': operation, 'request': request, 'started_at': datetime.now(timezone.utc).isoformat()}
        try:
            row['result'] = {'code': 'Success', 'output': getattr(client, operation)(**request)}
        except ClientError as error:
            row['result'] = {'code': error.response['Error']['Code'], 'error': error.response}
        row['finished_at'] = datetime.now(timezone.utc).isoformat()
        output['observations'].append(row)
        Path('/tmp/stackd_encryption_logging_extra.json').write_text(json.dumps(output, indent=2, default=lambda x: x.isoformat() if isinstance(x, datetime) else str(x)))
        print(row['label'], row['result']['code'], row['result'].get('output', {}).get('status'), flush=True)
